import io
import logging
import os
from typing import Optional

import torch
import torch.utils.data as data
from PIL import Image

from .readers import create_reader

_logger = logging.getLogger(__name__)


# max consecutive samples that fail to load (skipped w/ a warning) before raising
_ERROR_RETRY = int(os.environ.get('TIMM_DATASET_MAX_RETRIES') or 10)


class ImageDataset(data.Dataset):

    def __init__(
            self,
            root,
            reader=None,
            split='train',
            class_map=None,
            load_bytes=False,
            input_img_mode='RGB',
            transform=None,
            target_transform=None,
            additional_features=None,
            **kwargs,
    ):
        if reader is None or isinstance(reader, str):
            reader = create_reader(
                reader or '',
                root=root,
                split=split,
                class_map=class_map,
                additional_features=additional_features,
                **kwargs,
            )
        self.reader = reader
        self.load_bytes = load_bytes
        self.input_img_mode = input_img_mode
        self.transform = transform
        self.target_transform = target_transform
        self.additional_features = additional_features
        self._max_retries = _ERROR_RETRY

    def __getitem__(self, index):
        for attempt in range(self._max_retries):
            try:
                img, target, *features = self.reader[index]
                if self.load_bytes:
                    img = img.read()
                else:
                    img = Image.open(img)
                    if self.input_img_mode:
                        img = img.convert(self.input_img_mode)  # decodes pixels, so decode errors are skipped
                break
            except (IOError, OSError) as e:  # be specific
                _logger.warning(f'Skipped sample (index {index}). {e}')
                index = (index + 1) % len(self.reader)
        else:
            raise RuntimeError(f"Failed to load {self._max_retries} consecutive samples")

        if self.transform is not None:
            img = self.transform(img)

        if target is None:
            target = -1
        elif self.target_transform is not None:
            target = self.target_transform(target)

        if self.additional_features is None:
            return img, target
        else:
            return img, target, *features

    def __len__(self):
        return len(self.reader)

    def filename(self, index, basename=False, absolute=False):
        return self.reader.filename(index, basename, absolute)

    def filenames(self, basename=False, absolute=False):
        return self.reader.filenames(basename, absolute)


class IterableImageDataset(data.IterableDataset):

    def __init__(
            self,
            root,
            reader=None,
            split='train',
            class_map=None,
            is_training=False,
            batch_size=1,
            num_samples=None,
            seed=42,
            repeats=0,
            download=False,
            input_img_mode='RGB',
            input_key=None,
            target_key=None,
            transform=None,
            target_transform=None,
            max_steps=None,
            **kwargs,
    ):
        assert reader is not None
        if isinstance(reader, str):
            self.reader = create_reader(
                reader,
                root=root,
                split=split,
                class_map=class_map,
                is_training=is_training,
                batch_size=batch_size,
                num_samples=num_samples,
                seed=seed,
                repeats=repeats,
                download=download,
                input_img_mode=input_img_mode,
                input_key=input_key,
                target_key=target_key,
                max_steps=max_steps,
                **kwargs,
            )
        else:
            self.reader = reader
        self.transform = transform
        self.target_transform = target_transform

    def __iter__(self):
        for img, target in self.reader:
            if self.transform is not None:
                img = self.transform(img)
            if self.target_transform is not None:
                target = self.target_transform(target)
            yield img, target

    def __len__(self):
        if hasattr(self.reader, '__len__'):
            return len(self.reader)
        else:
            return 0

    def set_epoch(self, count):
        # TFDS and WDS need external epoch count for deterministic cross process shuffle
        if hasattr(self.reader, 'set_epoch'):
            self.reader.set_epoch(count)

    def set_loader_cfg(
            self,
            num_workers: Optional[int] = None,
    ):
        # TFDS and WDS readers need # workers for correct # samples estimate before loader processes created
        if hasattr(self.reader, 'set_loader_cfg'):
            self.reader.set_loader_cfg(num_workers=num_workers)

    def filename(self, index, basename=False, absolute=False):
        assert False, 'Filename lookup by index not supported, use filenames().'

    def filenames(self, basename=False, absolute=False):
        return self.reader.filenames(basename, absolute)


class AugMixDataset(torch.utils.data.Dataset):
    """Dataset wrapper to perform AugMix or other clean/augmentation mixes"""

    def __init__(self, dataset, num_splits=2):
        self.augmentation = None
        self.normalize = None
        self.dataset = dataset
        if self.dataset.transform is not None:
            self._set_transforms(self.dataset.transform)
        self.num_splits = num_splits

    def _set_transforms(self, x):
        assert isinstance(x, (list, tuple)) and len(x) == 3, 'Expecting a tuple/list of 3 transforms'
        self.dataset.transform = x[0]
        self.augmentation = x[1]
        self.normalize = x[2]

    @property
    def transform(self):
        return self.dataset.transform

    @transform.setter
    def transform(self, x):
        self._set_transforms(x)

    def _normalize(self, x):
        return x if self.normalize is None else self.normalize(x)

    def __getitem__(self, i):
        x, y = self.dataset[i]  # all splits share the same dataset base transform
        x_list = [self._normalize(x)]  # first split only normalizes (this is the 'clean' split)
        # run the full augmentation on the remaining splits
        for _ in range(self.num_splits - 1):
            x_list.append(self._normalize(self.augmentation(x)))
        return tuple(x_list), y

    def __len__(self):
        return len(self.dataset)

from abc import ABC, abstractmethod
from numbers import Integral
from typing import Dict, List, NamedTuple, Optional, Tuple, Union


LabelNames = Union[List[str], Tuple[str, ...], Dict[Union[int, str], str]]


class DatasetInfo(ABC):

    def __init__(self):
        pass

    @abstractmethod
    def num_classes(self):
        pass

    @abstractmethod
    def label_names(self):
        pass

    def label_indices(self) -> Tuple[int, ...]:
        """Return classifier indices that have label names."""
        return tuple(range(self.num_classes()))

    def has_label(self, index) -> bool:
        """Return whether a classifier index has a label name."""
        return 0 <= int(index) < self.num_classes()

    @abstractmethod
    def label_descriptions(self, detailed: bool = False, as_dict: bool = False) -> Union[List[str], Dict[str, str]]:
        pass

    @abstractmethod
    def index_to_label_name(self, index) -> str:
        pass

    @abstractmethod
    def index_to_description(self, index: int, detailed: bool = False) -> str:
        pass

    @abstractmethod
    def label_name_to_description(self, label: str, detailed: bool = False) -> str:
        pass


class CustomDatasetInfo(DatasetInfo):
    """ DatasetInfo that wraps passed values for custom datasets."""

    def __init__(
            self,
            label_names: LabelNames,
            label_descriptions: Optional[Dict[str, str]] = None
    ):
        super().__init__()
        if not isinstance(label_names, (list, tuple, dict)) or not label_names:
            raise ValueError('label_names must be a non-empty list, tuple, or index-to-name dictionary.')

        # Preserve the caller-facing container for backwards compatibility.
        self._label_names = label_names
        self._label_names_by_index = None
        if isinstance(label_names, dict):
            # JSON object keys are always strings, so normalize index keys when
            # loading model configs from the Hub. Dicts may be sparse.
            normalized_label_names = {}
            for raw_index, label_name in label_names.items():
                if not isinstance(raw_index, (Integral, str)):
                    raise TypeError(f'Label index must be an int or string, got {type(raw_index).__name__}.')
                try:
                    index = int(raw_index)
                except ValueError as e:
                    raise ValueError(f'Label index must be integer-like, got {raw_index!r}.') from e
                if index < 0:
                    raise ValueError(f'Label index must be non-negative, got {index}.')
                if index in normalized_label_names:
                    raise ValueError(f'Duplicate label index after normalization: {index}.')
                normalized_label_names[index] = label_name
            self._label_names_by_index = normalized_label_names
            label_name_values = normalized_label_names.values()
        else:
            label_name_values = label_names

        if not all(isinstance(name, str) for name in label_name_values):
            raise TypeError('All label names must be strings.')

        self._label_descriptions = label_descriptions  # label name => label description mapping
        if self._label_descriptions is not None:
            # validate descriptions (label names required)
            if not isinstance(self._label_descriptions, dict):
                raise TypeError('label_descriptions must be a label-name-to-description dictionary.')
            missing_descriptions = [name for name in label_name_values if name not in self._label_descriptions]
            if missing_descriptions:
                raise ValueError(f'Missing descriptions for label names: {missing_descriptions}.')

    def num_classes(self):
        return len(self._label_names)

    def label_names(self):
        return self._label_names

    def label_indices(self) -> Tuple[int, ...]:
        """Return classifier indices that have label names."""
        if self._label_names_by_index is not None:
            return tuple(self._label_names_by_index)
        return tuple(range(len(self._label_names)))

    def has_label(self, index) -> bool:
        """Return whether a classifier index has a label name."""
        index = int(index)
        if self._label_names_by_index is not None:
            return index in self._label_names_by_index
        return 0 <= index < len(self._label_names)

    def label_descriptions(self, detailed: bool = False, as_dict: bool = False) -> Union[List[str], Dict[str, str]]:
        return self._label_descriptions

    def label_name_to_description(self, label: str, detailed: bool = False) -> str:
        if self._label_descriptions:
            return self._label_descriptions[label]
        return label  # return label name itself if a descriptions is not present

    def index_to_label_name(self, index) -> str:
        if self._label_names_by_index is not None:
            return self._label_names_by_index[int(index)]
        assert 0 <= index < len(self._label_names)
        return self._label_names[index]

    def index_to_description(self, index: int, detailed: bool = False) -> str:
        label = self.index_to_label_name(index)
        return self.label_name_to_description(label, detailed=detailed)


class LabelMappingCoverage(NamedTuple):
    mapped: int
    missing: int
    extra: int


class DatasetInfoLabelMapper:
    """Map classifier indices to labels with reusable sparse-mapping fallback behavior."""

    def __init__(
            self,
            dataset_info: DatasetInfo,
            label_type: str = 'description',
            fallback_format: Optional[str] = '<unmapped:{index}>',
    ):
        if label_type not in ('name', 'description', 'detail', 'detailed'):
            raise ValueError(f'Invalid label type: {label_type}.')
        self.dataset_info = dataset_info
        self.label_type = label_type
        self.fallback_format = fallback_format

    def __call__(self, index) -> str:
        index = int(index)
        if not self.dataset_info.has_label(index) and self.fallback_format is not None:
            return self.fallback_format.format(index=index)
        if self.label_type == 'name':
            return self.dataset_info.index_to_label_name(index)
        return self.dataset_info.index_to_description(
            index,
            detailed=self.label_type in ('detail', 'detailed'),
        )

    def coverage(self, num_classes: int) -> LabelMappingCoverage:
        """Return mapped, missing, and out-of-range label counts for a classifier."""
        if num_classes < 0:
            raise ValueError(f'num_classes must be non-negative, got {num_classes}.')
        mapped_indices = self.dataset_info.label_indices()
        mapped = sum(0 <= index < num_classes for index in mapped_indices)
        return LabelMappingCoverage(
            mapped=mapped,
            missing=num_classes - mapped,
            extra=len(mapped_indices) - mapped,
        )

import csv
import os
import pkgutil
import re
from typing import Dict, List, Optional, Union

from .dataset_info import DatasetInfo


# NOTE no ambiguity wrt to mapping from # classes to ImageNet subset so far, but likely to change
_NUM_CLASSES_TO_SUBSET = {
    1000: 'imagenet-1k',
    11221: 'imagenet-21k-miil',  # miil subset of fall11
    11821: 'imagenet-12k',  # timm specific 12k subset of fall11
    21841: 'imagenet-22k',  # as in fall11.tar
    21842: 'imagenet-22k-ms',  # a Microsoft (for FocalNet) remapping of 22k w/ moves ImageNet-1k classes to first 1000
    21843: 'imagenet-21k-goog',  # Google's ImageNet full has two classes not in fall11
}

_SUBSETS = {
    'imagenet1k': 'imagenet_synsets.txt',
    'imagenet12k': 'imagenet12k_synsets.txt',
    'imagenet22k': 'imagenet22k_synsets.txt',
    'imagenet21k': 'imagenet21k_goog_synsets.txt',
    'imagenet21kgoog': 'imagenet21k_goog_synsets.txt',
    'imagenet21kmiil': 'imagenet21k_miil_synsets.txt',
    'imagenet22kms': 'imagenet22k_ms_synsets.txt',
}
_LEMMA_FILE = 'imagenet_synset_to_lemma.txt'
_DEFINITION_FILE = 'imagenet_synset_to_definition.txt'


def infer_imagenet_subset(model_or_cfg) -> Optional[str]:
    if isinstance(model_or_cfg, dict):
        num_classes = model_or_cfg.get('num_classes', None)
    else:
        num_classes = getattr(model_or_cfg, 'num_classes', None)
        if not num_classes:
            pretrained_cfg = getattr(model_or_cfg, 'pretrained_cfg', {})
            # FIXME at some point pretrained_cfg should include dataset-tag,
            # which will be more robust than a guess based on num_classes
            num_classes = pretrained_cfg.get('num_classes', None)
    if not num_classes or num_classes not in _NUM_CLASSES_TO_SUBSET:
        return None
    return _NUM_CLASSES_TO_SUBSET[num_classes]


class ImageNetInfo(DatasetInfo):

    def __init__(self, subset: str = 'imagenet-1k'):
        super().__init__()
        subset = re.sub(r'[-_\s]', '', subset.lower())
        assert subset in _SUBSETS, f'Unknown imagenet subset {subset}.'

        # WordNet synsets (part-of-speech + offset) are the unique class label names for ImageNet classifiers
        synset_file = _SUBSETS[subset]
        synset_data = pkgutil.get_data(__name__, os.path.join('_info', synset_file))
        self._synsets = synset_data.decode('utf-8').splitlines()

        # WordNet lemmas (canonical dictionary form of word) and definitions are used to build
        # the class descriptions. If detailed=True both are used, otherwise just the lemmas.
        lemma_data = pkgutil.get_data(__name__, os.path.join('_info', _LEMMA_FILE))
        reader = csv.reader(lemma_data.decode('utf-8').splitlines(), delimiter='\t')
        self._lemmas = dict(reader)
        definition_data = pkgutil.get_data(__name__, os.path.join('_info', _DEFINITION_FILE))
        reader = csv.reader(definition_data.decode('utf-8').splitlines(), delimiter='\t')
        self._definitions = dict(reader)

    def num_classes(self):
        return len(self._synsets)

    def label_names(self):
        return self._synsets

    def label_descriptions(self, detailed: bool = False, as_dict: bool = False) -> Union[List[str], Dict[str, str]]:
        if as_dict:
            return {label: self.label_name_to_description(label, detailed=detailed) for label in self._synsets}
        else:
            return [self.label_name_to_description(label, detailed=detailed) for label in self._synsets]

    def index_to_label_name(self, index) -> str:
        assert 0 <= index < len(self._synsets), \
            f'Index ({index}) out of range for dataset with {len(self._synsets)} classes.'
        return self._synsets[index]

    def index_to_description(self, index: int, detailed: bool = False) -> str:
        label = self.index_to_label_name(index)
        return self.label_name_to_description(label, detailed=detailed)

    def label_name_to_description(self, label: str, detailed: bool = False) -> str:
        if detailed:
            description = f'{self._lemmas[label]}: {self._definitions[label]}'
        else:
            description = f'{self._lemmas[label]}'
        return description
